import type { Plugin } from "vite";

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const HEADER = [
  "// @generated by tooling/message-types.ts from the English catalogue; do not edit.",
  '// Строковые литералы дают типы ключей и аргументов ICU для t("key", args).',
  "",
].join("\n");

/** Пишет рядом с каждым английским каталогом `<ns>.d.json.ts` с литеральными типами сообщений. */
export function writeMessageTypes(englishDir: string): number {
  const files = readdirSync(englishDir).filter((file) => file.endsWith(".json"));
  for (const file of files) {
    const messages: unknown = JSON.parse(readFileSync(join(englishDir, file), "utf8"));
    const declaration = `${HEADER}declare const messages: ${JSON.stringify(messages, null, 2)};\nexport default messages;\n`;
    const target = join(englishDir, file.replace(/\.json$/, ".d.json.ts"));
    let current = "";
    try {
      current = readFileSync(target, "utf8");
    } catch {
      current = "";
    }
    if (current !== declaration) writeFileSync(target, declaration);
  }
  return files.length;
}

/** Поддерживает объявления в актуальном состоянии при сборке и при правке английских каталогов. */
export function messageTypes(englishDir: string): Plugin {
  return {
    name: "whisperer:message-types",
    buildStart() {
      writeMessageTypes(englishDir);
    },
    configureServer(server) {
      server.watcher.on("change", (path) => {
        if (path.startsWith(englishDir) && path.endsWith(".json")) writeMessageTypes(englishDir);
      });
    },
  };
}
